import{_ as s,C as n,o,c as e,j as t,E as l,a as r,a2 as d}from"./chunks/framework.C21TwvGF.js";const q=JSON.parse(`{"title":"5-hafta (Mentor)","description":"","frontmatter":{"title":"5-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"n":5,"bob":"II-bob · 2D grafika asoslari va Photoshop","lessons":[{"g":13,"title":"O'yin uchun ikonka va spraytlar yaratish (3-qism): Sprayt sheet (atlas) tayyorlash va optimallashtirish","lead":"Qahramoningiz yurishi uchun 6 ta rasm kerak, tangalar, zelyelar, kalitlar uchun yana o'nlab. Ularni bitta tartibli faylga yig'sak, o'yin tezroq ishlaydi. Bugun shu faylni — sprayt sheet'ni yaratamiz.","link":"/mentor/9-sinf-game/hafta-05/dars-1","slide":"/slaydlar/9-sinf-game/hafta-05/dars-1.html","test":"/slaydlar/9-sinf-game/hafta-05/dars-1-test.html"},{"g":14,"title":"UI dizayn: tugmalar, menyular, HUD (1-qism): Tugmalar turlari, holatlari (Normal, Hover, Pressed)","lead":"«START» tugmasini bosganingizda u biroz botib ketadi va o'yin boshlanadi. Shu kichik o'zgarish — dizaynerning puxta ishi. Bugun o'yin tugmalarini o'zimiz yaratamiz.","link":"/mentor/9-sinf-game/hafta-05/dars-2","slide":"/slaydlar/9-sinf-game/hafta-05/dars-2.html","test":"/slaydlar/9-sinf-game/hafta-05/dars-2-test.html"},{"g":15,"title":"UI dizayn: tugmalar, menyular, HUD (2-qism): Bosh menyu, sozlamalar va pauza menyusi dizayni","lead":"O'yin bilan birinchi uchrashuv — bosh menyu. U o'yinchiga «xush kelibsiz» deydi va yo'l ko'rsatadi. Bugun o'yiningiz uchun bosh menyu va pauza menyusini yaratamiz.","link":"/mentor/9-sinf-game/hafta-05/dars-3","slide":"/slaydlar/9-sinf-game/hafta-05/dars-3.html","test":"/slaydlar/9-sinf-game/hafta-05/dars-3-test.html"}],"test":"/slaydlar/9-sinf-game/hafta-05/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-05/index.md","filePath":"mentor/9-sinf-game/hafta-05/index.md"}`),h={name:"mentor/9-sinf-game/hafta-05/index.md"},m={class:"blk"},u={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},y={class:"blk"},g={id:"baholash-mezoni",tabindex:"-1"};function b(c,a,f,v,p,k){const i=n("Icon");return o(),e("div",null,[t("div",m,[t("h2",u,[l(i,{name:"house"}),a[0]||(a[0]=r(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=t("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=d('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan. Barcha fayllarni bitta <code>5-hafta_Ism</code> papkasida saqlang — tugma va menyular 6-haftada (HUD va prototip) kerak bo&#39;ladi.</p><hr><h2 id="_13-dars-sprayt-sheet-atlas-tayyorlash-va-optimallashtirish" tabindex="-1">13-dars: Sprayt sheet (atlas) tayyorlash va optimallashtirish <a class="header-anchor" href="#_13-dars-sprayt-sheet-atlas-tayyorlash-va-optimallashtirish" aria-label="Permalink to &quot;13-dars: Sprayt sheet (atlas) tayyorlash va optimallashtirish&quot;">​</a></h2><ol><li>Qahramoningiz uchun idle (2 kadr) va yurish (4 kadr) animatsiyalaridan bitta <strong>128×64 px</strong> sheet tayyorlang: 1-qator — idle, 2-qator — yurish, kataklar 32×32.</li><li>Oyoq chizig&#39;i (tayanch nuqta) barcha kadrlarda bir xil ekanini gorizontal guide bilan tekshiring.</li><li>12-darsdagi obyektlaringizdan (kamida 4 ta) <strong>64×64 px</strong> atlas yig&#39;ing (16×16 kataklar, o&#39;xshashlari bir qatorda).</li><li>Ikkalasini shaffof PNG, 100% qilib eksport qiling va qoidaga ko&#39;ra nomlang.</li></ol><p><strong>Kutiladigan natija:</strong> <code>qahramon_sheet_32x32.png</code>, <code>obyektlar_atlas_16x16.png</code> va <code>.psd</code> fayllar.</p><hr><h2 id="_14-dars-tugmalar-turlari-holatlari-normal-hover-pressed" tabindex="-1">14-dars: Tugmalar turlari, holatlari (Normal, Hover, Pressed) <a class="header-anchor" href="#_14-dars-tugmalar-turlari-holatlari-normal-hover-pressed" aria-label="Permalink to &quot;14-dars: Tugmalar turlari, holatlari (Normal, Hover, Pressed)&quot;">​</a></h2><ol><li>O&#39;yiningiz uslubida Primary («START») va Secondary («ORTGA») tugmalarni yarating (Rectangle Tool, Corners, Stroke, Text Tool).</li><li>Har biri uchun Normal, Hover va Pressed holatlarini alohida nomlangan qatlamlarda tayyorlang.</li><li>Barcha holatlarni bir xil kanvas o&#39;lchamida, shaffof PNG qilib eksport qiling (6 ta fayl).</li></ol><p><strong>Kutiladigan natija:</strong> <code>btn_start_normal.png</code> … <code>btn_ortga_pressed.png</code> va <code>.psd</code> fayl.</p><hr><h2 id="_15-dars-bosh-menyu-sozlamalar-va-pauza-menyusi-dizayni" tabindex="-1">15-dars: Bosh menyu, sozlamalar va pauza menyusi dizayni <a class="header-anchor" href="#_15-dars-bosh-menyu-sozlamalar-va-pauza-menyusi-dizayni" aria-label="Permalink to &quot;15-dars: Bosh menyu, sozlamalar va pauza menyusi dizayni&quot;">​</a></h2><ol><li>1920×1080 hujjatda bosh menyu yarating: «MENU» sarlavhasi, START, Sozlamalar, Chiqish (qizil), Solid Color fon, 2 ta bezak doira.</li><li>Qatlamlarni <code>Ctrl + G</code> bilan guruhlang va nomlang (<code>Main Menu</code>).</li><li>Shu uslubda pauza menyusini chizing: qorong&#39;ilashtirilgan o&#39;yin sahnasi, panel, «PAUZA», Davom etish / Sozlamalar / Bosh menyuga.</li><li>Ikkala ekranni PNG qilib eksport qiling.</li></ol><p><strong>Kutiladigan natija:</strong> <code>bosh_menyu.png</code>, <code>pauza_menyu.png</code> va <code>.psd</code> fayl.</p><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-jami-100-ball" tabindex="-1">Baholash mezonlari (Jami 100 ball) <a class="header-anchor" href="#baholash-mezonlari-jami-100-ball" aria-label="Permalink to &quot;Baholash mezonlari (Jami 100 ball)&quot;">​</a></h3><ul><li><strong>13-dars vazifasi (30 ball):</strong> teng kataklar, to&#39;g&#39;ri o&#39;lcham hisobi, bir xil tayanch nuqta, atlasda tartib, shaffof PNG 100%, nomlash qoidasi.</li><li><strong>14-dars vazifasi (35 ball):</strong> Primary/Secondary ierarxiyasi, 3 holat aniq farqlanadi (kamida 2 belgi bilan), alohida qatlamlar, bir xil kanvas, shaffof PNG.</li><li><strong>15-dars vazifasi (35 ball):</strong> 3 tugmali vertikal menyu teng oraliqda, sarlavha va fon, guruhlangan va nomlangan qatlamlar, pauza menyusida xira sahna va yagona uslub.</li></ul><h3 id="eslatma" tabindex="-1">Eslatma <a class="header-anchor" href="#eslatma" aria-label="Permalink to &quot;Eslatma&quot;">​</a></h3><ul><li><code>.psd</code> fayllar ham topshirilsin — qatlam nomlari va guruhlarni tekshirish uchun.</li><li>6-haftada HUD va prototiplash uchun shu tugma va menyulardan foydalaniladi.</li></ul>',19))]),t("div",y,[t("h2",g,[l(i,{name:"list-checks"}),a[3]||(a[3]=r(" Baholash mezoni ",-1)),a[4]||(a[4]=t("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=d('<p><strong>Mavzular:</strong></p><ol><li>O&#39;yin uchun ikonka va spraytlar yaratish (3-qism): Sprayt sheet (atlas) tayyorlash va optimallashtirish</li><li>UI dizayn: tugmalar, menyular, HUD (1-qism): Tugmalar turlari, holatlari (Normal, Hover, Pressed)</li><li>UI dizayn: tugmalar, menyular, HUD (2-qism): Bosh menyu, sozlamalar va pauza menyusi dizayni</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Sprayt sheet va atlas</strong></td><td>Teng kataklar, o&#39;lcham hisobi, padding, tayanch nuqta, atlasda tartib, optimallashtirish, PNG 100% va nomlash</td><td>30 ball</td></tr><tr><td><strong>Tugmalar</strong></td><td>UI dizayn tushunchasi, Primary/Secondary, dizayn talablari, Normal/Hover/Pressed holatlari alohida qatlamlarda, Layer Styles me&#39;yorida, shaffof PNG</td><td>35 ball</td></tr><tr><td><strong>Menyular</strong></td><td>Menyu turlari, vertikal/gorizontal, ikonka va matn uyg&#39;unligi, bosh menyu (sarlavha, 3 tugma, fon, bezak), guruhlash, pauza menyusi, eksport</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><p>Dasturdagi shkala: <strong>90–100 — 5</strong>, <strong>71–89 — 4</strong>, <strong>60–70 — 3</strong>, <strong>0–59 — 2</strong>.</p><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Sheet/atlas (30)</th><th>Tugmalar (35)</th><th>Menyular (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-uchun-eslatmalar" tabindex="-1">Mentor uchun eslatmalar <a class="header-anchor" href="#mentor-uchun-eslatmalar" aria-label="Permalink to &quot;Mentor uchun eslatmalar&quot;">​</a></h2><ul><li>13-darsda dvijokdagi kesish (Unity Sprite Editor) faqat so&#39;z bilan tushuntiriladi — amalda Unity bo&#39;limida o&#39;tiladi.</li><li>14–15-darslar uslubiy ko&#39;rsatmaning 1.4-mashg&#39;uloti asosida: «O&#39;yin menyusi» hujjati ikki dars davomida to&#39;ldiriladi.</li><li>Kuchli o&#39;quvchilarga: Disabled holati, gorizontal tablar va mobil (1080×1920) menyu versiyasi.</li></ul>',12))])])}const _=s(h,[["render",b]]);export{q as __pageData,_ as default};
